// Auto-mapped asset universe — the whole tokenized-stock market, not a curated
// sample. src/data/universe.json is generated by scripts/build-universe.mjs
// (CoinGecko category census → issuer-pattern ticker derivation → Finnhub
// validation); regenerate it there, don't hand-edit. Records with
// underlying:null are NAV/unlisted products shown token-only (no premium).

import raw from './universe.json'

const ISSUER_META = {
  xStocks: { chain: 'Solana', venues: ['Kraken', 'Bybit', 'Gate.io', 'KuCoin', 'Jupiter'] },
  Ondo: { chain: 'Ethereum', venues: ['Ondo Global Markets'] },
}

export const ASSETS = raw.map((a) => ({
  ...a,
  chain: ISSUER_META[a.issuer]?.chain ?? null,
  venues: ISSUER_META[a.issuer]?.venues ?? [],
}))

export const ASSET_IDS = ASSETS.map((a) => a.id)

export const BY_ID = Object.fromEntries(ASSETS.map((a) => [a.id, a]))

// Continuous polling covers the top of the market by cap (>99% of tracked
// value — keeps the Home "market value" hero honest on one API chunk-set);
// the long tail is fetched on demand when a screen subscribes to it.
export const CORE_IDS = [...ASSETS]
  .sort((a, b) => b.cap - a.cap)
  .slice(0, 250)
  .map((a) => a.id)
